#pragma once

template <typename T>
class Register {
public:
    // Data members
    T prev;      // Previous value (output of the register)
    T next;      // Next value (input to be written)
    bool _stall; // Stall flag

    // Constructors
    Register();                          // Default constructor
    Register(T d);                       // Parameterized constructor

    // Member functions
    T read() const;                      // Read current output
    T current() const;                   // Get next value (input)
    void write(const T &t);              // Write new input value
    void tick();                         // Update register state
    void stall(bool stall);               // Control stalling

    // Operators
    operator T() const;                  // Conversion to T
    void operator=(T next);              // Assignment from T
};

// Default constructor
template <typename T>
Register<T>::Register() : prev(static_cast<T>(0)), next(static_cast<T>(0)), _stall(false) {}

// Parameterized constructor
template <typename T>
Register<T>::Register(T d) : prev(d), next(d), _stall(false) {}

// Read current output
template <typename T>
T Register<T>::read() const {
    return prev;
}

// Get next value (input)
template <typename T>
T Register<T>::current() const {
    return next;
}

// Write new input value
template <typename T>
void Register<T>::write(const T &t) {
    next = t;
}

// Update register state
template <typename T>
void Register<T>::tick() {
    if (!_stall) {
        prev = next;
    }
}

// Control stalling
template <typename T>
void Register<T>::stall(bool stall) {
    _stall = stall;
}

// Conversion to T
template <typename T>
Register<T>::operator T() const {
    return prev;
}

// Assignment from T
template <typename T>
void Register<T>::operator=(T next) {
    write(next);
}
